`timescale 1ns/1ps
module tb_arithmetic;
reg signed[15:0]a,b;reg signed[31:0]acc;wire signed[31:0]qres;wire qsat;reg[15:0]fa,fb;wire[15:0]fres;wire finv,fovf,funf;integer checks,fails;
sf_fixed_q15_mac q(.a_q15(a),.b_q15(b),.acc_q15(acc),.result_q15(qres),.saturated(qsat));sf_fp16_mul f(.a(fa),.b(fb),.result(fres),.invalid(finv),.overflow(fovf),.underflow(funf));
task check_q;input signed[15:0]ta,tb;input signed[31:0]tacc,expected;input expected_sat;begin a=ta;b=tb;acc=tacc;#1;checks=checks+1;if(qres!==expected||qsat!==expected_sat)begin $display("FAIL Q15 a=%0d b=%0d acc=%0d got=%0d sat=%b exp=%0d/%b",ta,tb,tacc,qres,qsat,expected,expected_sat);fails=fails+1;end end endtask
task check_f;input[15:0]ta,tb,expected;input ei,eo,eu;begin fa=ta;fb=tb;#1;checks=checks+1;if(fres!==expected||finv!==ei||fovf!==eo||funf!==eu)begin $display("FAIL FP16 a=%h b=%h got=%h flags=%b%b%b exp=%h/%b%b%b",ta,tb,fres,finv,fovf,funf,expected,ei,eo,eu);fails=fails+1;end end endtask
initial begin $dumpfile("build/tb_arithmetic.vcd");$dumpvars(0,tb_arithmetic);checks=0;fails=0;a=0;b=0;acc=0;fa=0;fb=0;check_q(16'sh4000,16'sh4000,0,32'sd8192,0);check_q(-16'sh4000,16'sh4000,0,-32'sd8192,0);check_q(16'sh7fff,16'sh7fff,0,32'sd32766,0);check_q(16'sh4000,16'sh4000,32'sh7ffff000,32'sh7fffffff,1);check_f(16'h3E00,16'h4000,16'h4200,0,0,0);check_f(16'hC000,16'h3800,16'hBC00,0,0,0);check_f(16'h0000,16'h4500,16'h0000,0,0,0);check_f(16'h7BFF,16'h4000,16'h7C00,0,1,0);check_f(16'h7C00,16'h0000,16'h7E00,1,0,0);check_f(16'h0001,16'h3C00,16'h0000,0,0,1);if(fails==0)$display("TEST_RESULT: PASS arithmetic checks=%0d",checks);else $display("TEST_RESULT: FAIL arithmetic checks=%0d fails=%0d",checks,fails);$finish(fails!=0);end
endmodule
